// Darkest Dungeon stress pop up animation
const tokens = canvas.tokens.controlled;
const config = {
  isStress: true, // If true play Stress animation, if false plays Relief animation
  delayPerToken: 150, // Delay in MS between tokens
  volume: 1, // 1 = 100%
  duration: 1500, // How long to play it in MS
  users: game.users.contents.map(u => u.id) // list of user IDs to play for
}


game.genga.api.darkestDungeonStress(tokens, config);
